import type { configType } from "./bootstrap";
// This is a singleton class to store the configuration object on bootstrap

class SingletonConfig {
	config: configType;
	constructor() {
		this.config = {};
	}
	getConfig() {
		return this.config;
	}
	setConfig(config: configType) {
		this.config = config;
	}
}

export default new SingletonConfig();
