import { getURL, injectTag } from "../bootstrap";

type ThemeStylesheetConfig = {
	darkModeClass?: string;
	classic?: boolean;
	blue?: boolean;
	themes?: {
		light?: { name: string; path: string };
		dark?: { name: string; path: string };
		classicLight?: { name: string; path: string };
		classicDark?: { name: string; path: string };
		onecdColor?: { name: string; path: string };
		onecdLight?: { name: string; path: string };
		onecdDark?: { name: string; path: string };
	};
	target?: HTMLElement;
};

type ThemeStylesheetController = {
	disconnect: () => void;
};

function setTheme(name: string, path: string, enable: boolean) {
	const link = document.querySelector(
		`link[data-token="${name}"]`,
	) as HTMLLinkElement | null;
	if (enable) {
		if (link) {
			link.disabled = false;
		} else {
			injectTag({
				predicate: true,
				tag: "link",
				rel: "stylesheet",
				href: path,
				"data-token": name,
				prepend: true,
			});
		}
	} else if (link) {
		link.disabled = true;
	}
}

export function loadThemeStylesheets(
	options: ThemeStylesheetConfig = {},
): ThemeStylesheetController {
	if (typeof document === "undefined") {
		return { disconnect: () => undefined };
	}

	const {
		darkModeClass = "hbr-mode-dark",
		classic = true,
		blue = false,
		themes = {},
		target: observedTarget,
	} = options;

	const target = observedTarget ?? document.body;
	if (!target) {
		return { disconnect: () => undefined };
	}

	const themeDir = blue ? "styles/base/themes/blue/" : "styles/base/themes/";

	const resolved = {
		light: {
			name: "light",
			path: getURL(`${themeDir}token-theme-light-variables.css`),
			...themes.light,
		},
		dark: {
			name: "dark",
			path: getURL(`${themeDir}token-theme-dark-variables.css`),
			...themes.dark,
		},
		classicLight: {
			name: "classic-light",
			path: getURL(`${themeDir}token-theme-classic-light-variables.css`),
			...themes.classicLight,
		},
		classicDark: {
			name: "classic-dark",
			path: getURL(`${themeDir}token-theme-classic-dark-variables.css`),
			...themes.classicDark,
		},
		onecdColor: {
			name: "onecd-color",
			path: getURL("styles/base/tokens/onecd/color.css"),
			...themes.onecdColor,
		},
		onecdLight: {
			name: "onecd-light",
			path: getURL("styles/base/tokens/onecd/light.css"),
			...themes.onecdLight,
		},
		onecdDark: {
			name: "onecd-dark",
			path: getURL("styles/base/tokens/onecd/dark.css"),
			...themes.onecdDark,
		},
	};

	const updateTheme = () => {
		const isDark = target.classList.contains(darkModeClass);
		const isOnecd = target.getAttribute("data-theme") === "onecd";

		setTheme(
			resolved.light.name,
			resolved.light.path,
			!isOnecd && !classic && !isDark,
		);
		setTheme(
			resolved.dark.name,
			resolved.dark.path,
			!isOnecd && !classic && isDark,
		);
		setTheme(
			resolved.classicLight.name,
			resolved.classicLight.path,
			!isOnecd && classic && !isDark,
		);
		setTheme(
			resolved.classicDark.name,
			resolved.classicDark.path,
			!isOnecd && classic && isDark,
		);
		setTheme(
			resolved.onecdLight.name,
			resolved.onecdLight.path,
			isOnecd && !isDark,
		);
		setTheme(
			resolved.onecdDark.name,
			resolved.onecdDark.path,
			isOnecd && isDark,
		);
		setTheme(resolved.onecdColor.name, resolved.onecdColor.path, isOnecd);
	};

	updateTheme();

	const observer = new MutationObserver(updateTheme);
	observer.observe(target, {
		attributes: true,
		attributeFilter: ["class", "data-theme"],
	});

	return { disconnect: () => observer.disconnect() };
}

export type { ThemeStylesheetConfig, ThemeStylesheetController };
