import { setNonce } from "@stencil/core";
import { version } from "../package.json";

import singletonConfig from "./singleton-config";

export type configType = {
	// nonce for script and style tags injected dynamically
	nonce?: string;
	// flag to add nonce to meta tag
	nonceMeta?: boolean;
	// base path for assets: tokens, theme css, icons and JS for self-lazy loaded components
	base?: string;
	// The absolute path to the folder containing the system icons, it applies when `name` & `library` are provided.
	iconAssetPath?: string;
	/** Scripts **/
	// flag to inject self-lazy loaded components' JS
	injectScript?: boolean;

	/** Styles **/
	// flag to inject components' base style css
	injectStyle?: boolean;
	// base font size for the app if not using the default 16px, supported values are 10, 14. works in combination with injectTokens: true
	baseFont?: string;
	// flag to inject tokens css
	injectTokens?: boolean;
	// flag to inject dark mode tokens
	injectDarkTokens?: boolean;

	// [magnetic only] flag to inject "magnetic" theme css
	injectMagneticTheme?: boolean;
	// [magnetic only] flag to inject dark mode "magnetic" theme css
	injectMagneticDarkTheme?: boolean;
	// [magnetic only] flag to inject "magnetic classic" theme for status colors (green/yellow/red 🟢🟡🔴)
	injectMagneticClassicTheme?: boolean;
	// [magnetic only] flag to inject "magnetic alternative" theme for brand colors (blue 🟦 instead of green)
	injectMagneticBrandAltTheme?: boolean;
	// [magnetic only] flag to inject OneCD light mode tokens
	injectOneCDTokens?: boolean;
	// [magnetic only] flag to inject OneCD dark mode tokens
	injectOneCDDarkTokens?: boolean;
	// [BETA: DO NOT USE, OneCD only] flag to inject OneCD theme css
	injectOneCDTheme?: boolean;
	// [BETA: DO NOT USE, OneCD only] flag to inject OneCD dark theme css
	injectOneCDDarkTheme?: boolean;

	injectBaseTokens?: boolean;
	injectBaseMagneticTheme?: boolean;
	injectMagneticLightTokens?: boolean;
	injectMagneticDarkTokens?: boolean;
	injectMagneticClassicLightTokens?: boolean;
	injectMagneticClassicDarkTokens?: boolean;

	// query string to append to the injected script and style tags for cache busting
	queryString?: string;

	systemIcons?: {
		[key: string]: string;
	};

	// TODO
	// cache busting with package version
	// service worker support
	// flash of unstyled content (FOUC) handling
	// prefetching of components
	// default properties for components
	// system icon svg strings
};

export type bootstrapTagType = {
	predicate?: boolean;
	tag: string;
	href?: string | string[];
	src?: string;
	rel?: string;
	type?: string;
	async?: boolean;
	title?: string;
	[key: string]: unknown;
};

/** Default configuration object */
const config: configType = singletonConfig.getConfig();

const getURL = (path: string) => {
	const urlString = config.base
		? `${config.base}${path}`
		: `/harbor-elements/${path}`;
	const queryString = config.queryString
		? `?${config.queryString}`
		: `?v=${version}`;
	return `${urlString}${queryString}`;
};

type singleHrefTag = Omit<bootstrapTagType, "href"> & { href?: string };

const createAndInsert = (tag: singleHrefTag) => {
	const tagEl = document.createElement(tag.tag as string);
	Object.keys(tag).forEach((key) => {
		if (!["tag", "predicate", "href", "prepend"].includes(key)) {
			tagEl.setAttribute(key, String(tag[key]));
		}
	});
	if (tag.href) {
		tagEl.setAttribute("href", tag.href);
	}
	if (config.nonce) {
		tagEl.nonce = config.nonce;
	}
	if (tag.prepend) {
		document.head.prepend(tagEl);
	} else {
		document.head.appendChild(tagEl);
	}
};

function injectTag(tag: bootstrapTagType) {
	if (!tag.predicate) return;

	if (Array.isArray(tag.href)) {
		tag.href.forEach((href) => createAndInsert({ ...tag, href }));
	} else {
		createAndInsert(tag as singleHrefTag);
	}
}

// *** NOTES ***
// Per documentation, bootstrap will be invoked from the autoloading loader (from public/harbor-elements/)
// This function ideally should only have non side effecting code like inserting script tags
// Any getters should be part of something like a DOM node, that can be queried by other components irrespective of which loader the bootstrap is called from

/**
 * Method to bootstrap the library with initial configuration
 * @param _config configuration object set by the consuming app
 */
function bootstrap(_config: configType): void {
	// check if environment is browser
	if (!(typeof window !== "undefined")) return;

	// updates config object
	for (const key in _config) {
		config[key] = _config[key];
	}

	if (typeof document !== "undefined") {
		const metaEl = document.createElement("meta");
		metaEl.id = "hbr-internal__meta";
		metaEl["__internal-config"] = config;
		document.head.appendChild(metaEl);
	}

	// sets nonce, and calls stencil's setNonce
	if (config.nonce) {
		// For prod mode, stencil adds constructed stylesheets
		setNonce(config.nonce);
		// For local development or optionally in production, add nonce to the meta tag
		if (window.location.hostname.includes("localhost") || config.nonceMeta) {
			const nonceEl = document.createElement("meta");
			nonceEl.setAttribute("name", "csp-nonce");
			nonceEl.setAttribute("content", config.nonce);
			document.head.appendChild(nonceEl);
		}
	}

	const tokensPath = ["10", "14"].includes(config.baseFont)
		? `styles/tokens/base-font-${config.baseFont}`
		: "styles/tokens";

	const tagsToInject = [
		{
			predicate: config.injectScript,
			src: getURL("harbor-elements.esm.js"),
			type: "module",
			async: true,
			tag: "script",
		},
		{
			predicate: config.injectStyle,
			rel: "stylesheet",
			href: getURL("harbor-elements.css"),
			tag: "link",
		},
		{
			predicate: config.injectMagneticTheme,
			rel: "stylesheet",
			href: getURL("styles/themes/magnetic.css"),
			tag: "link",
		},
		{
			predicate: config.injectTokens,
			rel: "stylesheet",
			href: getURL(`${tokensPath}/magnetic.css`),
			tag: "link",
		},
		{
			predicate: config.injectMagneticDarkTheme,
			rel: "stylesheet",
			href: getURL("styles/themes/magnetic.dark.css"),
			tag: "link",
		},
		{
			predicate: config.injectDarkTokens,
			rel: "stylesheet",
			href: getURL(`${tokensPath}/magnetic.dark.css`),
			tag: "link",
		},
		{
			predicate: config.injectMagneticClassicTheme,
			rel: "stylesheet",
			href: getURL("styles/themes/magnetic-classic.css"),
			tag: "link",
			title: "hbr-theme-magnetic-classic",
		},
		{
			predicate: config.injectMagneticBrandAltTheme,
			rel: "stylesheet",
			href: getURL("styles/themes/magnetic-brand-alt.css"),
			tag: "link",
		},
		{
			predicate: config.injectOneCDTokens,
			rel: "stylesheet",
			"data-token": "onecd",
			href: [
				getURL("styles/themes/onecd-token-color-variables.css"),
				getURL("styles/themes/onecd-token.light.css"),
			],
			tag: "link",
		},
		{
			predicate: config.injectOneCDDarkTokens,
			rel: "stylesheet",
			"data-token": "onecd-dark",
			href: getURL("styles/themes/onecd-token.dark.css"),
			tag: "link",
		},
		{
			predicate: config.injectMagneticLightTokens,
			rel: "stylesheet",
			"data-token": "light",
			href: getURL("styles/base/themes/token-theme-light-variables.css"),
			tag: "link",
		},
		{
			predicate: config.injectMagneticDarkTokens,
			rel: "stylesheet",
			"data-token": "dark",
			href: getURL("styles/base/themes/token-theme-dark-variables.css"),
			tag: "link",
		},
		{
			predicate: config.injectMagneticClassicLightTokens,
			rel: "stylesheet",
			"data-token": "classic-light",
			href: getURL(
				"styles/base/themes/token-theme-classic-light-variables.css",
			),
			tag: "link",
		},
		{
			predicate: config.injectMagneticClassicDarkTokens,
			rel: "stylesheet",
			"data-token": "classic-dark",
			href: getURL("styles/base/themes/token-theme-classic-dark-variables.css"),
			tag: "link",
		},
		{
			predicate: config.injectBaseTokens,
			rel: "stylesheet",
			"data-token": "base",
			href: [
				getURL("styles/base/tokens/base.css"),
				getURL("styles/base/tokens/magnetic.css"),
			],
			tag: "link",
		},
		{
			predicate: config.injectBaseMagneticTheme,
			rel: "stylesheet",
			href: getURL("styles/base/themes/magnetic.css"),
			"data-theme": "base-magnetic",
			tag: "link",
		},
		{
			predicate: config.injectOneCDTheme,
			rel: "stylesheet",
			"data-theme": "onecd-light",
			href: getURL("styles/themes/onecd.css"),
			tag: "link",
		},
		{
			predicate: config.injectOneCDDarkTheme,
			rel: "stylesheet",
			"data-theme": "onecd-dark",
			href: getURL("styles/themes/onecd.dark.css"),
			tag: "link",
		},
	];

	tagsToInject.forEach(injectTag);
}

/**
 * To be removed after all components are updated to use hbr-config
 */
const getBootstrapConfig = () => {
	return config;
};
export { bootstrap, getBootstrapConfig, getURL, injectTag };
